package com.muthumol.player.dummy;
import android.view.*;
import android.widget.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w412dp-h915dp-mdpi")
public class PhoneCompatibilityTest {
 @Test public void modernPhoneUsesPortraitTouchLayoutAndCorrectAppName(){org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create();try{MainActivity a=c.get();assertTrue(a.phoneLayout());assertEquals(35,a.getApplicationInfo().targetSdkVersion);assertEquals("TG stream",a.getApplicationInfo().loadLabel(a.getPackageManager()).toString());assertNotEquals(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,a.getRequestedOrientation());assertTrue(a.homeActions[2].getLayoutParams().height>=Ui.dp(a,48));assertEquals("Search",a.homeActions[2].getText().toString());assertEquals(a.moreButton.getId(),a.heroContinueButton.getNextFocusRightId());}finally{c.destroy();}}
 @Test public void phoneHasUpdaterEvenWhenLoginBuildConfigurationIsMissing(){org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create();try{MainActivity a=c.get();a.configuration();boolean found=false;for(int i=0;i<a.column.getChildCount();i++){View v=a.column.getChildAt(i);if(v instanceof Button&&((Button)v).getText().toString().equals("Check for update"))found=true;assertFalse(v instanceof EditText);}assertTrue(found);}finally{c.destroy();}}
 @Test @Config(sdk=28,qualifiers="w412dp-h915dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) public void phoneHomeRendersWithVisibleTouchActions()throws Exception{org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create();c.start().resume().visible();MainActivity a=c.get();Movie previous=a.session.movie;java.util.List<Movie> recent=a.session.recentMovies;try{Movie one=new Movie();one.title="LOST.S01E01.mkv";one.identity="phone-lost-1";Movie two=new Movie();two.title="LOST.S02E01.mkv";two.identity="phone-lost-2";a.session.movie=one;a.session.recentMovies=java.util.Arrays.asList(one,two);a.home();View root=a.findViewById(android.R.id.content);root.measure(View.MeasureSpec.makeMeasureSpec(412,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(915,View.MeasureSpec.EXACTLY));root.layout(0,0,412,915);org.robolectric.shadows.ShadowLooper.idleMainLooper();android.graphics.Rect bounds=new android.graphics.Rect();assertTrue("Primary action not visible",a.heroContinueButton.getGlobalVisibleRect(bounds));assertTrue("Primary touch action clipped: "+bounds,bounds.height()>=Ui.dp(a,48));assertEquals(1,a.movieCards.size());assertEquals("LOST",a.movieCards.get(0).name.getText().toString());android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(412,915,android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(image));try(java.io.FileOutputStream out=new java.io.FileOutputStream("/tmp/tg-stream-phone.png")){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}finally{a.session.movie=previous;a.session.recentMovies=recent;c.destroy();}}
 @Test public void audioRouteReceiverCanStartWithoutBluetoothPermissionOnModernAndroid(){org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create();try{BluetoothControls controls=new BluetoothControls(c.get(),()->{});controls.start();assertTrue(controls.registered);controls.stop();assertFalse(controls.registered);}finally{c.destroy();}}
}

